import requests

API_URL = "https://api-inference.huggingface.co/models/sentence-transformers/all-MiniLM-L6-v2"
headers = {"Authorization": "Bearer YOUR_API_KEY"}

def query(payload):
    response = requests.post(API_URL, headers=headers, json=payload)
    return response.json()

def embed_moderation_rationale(rationale):
    payload = {"inputs": rationale}
    result = query(payload)
    return result

# Example usage
rationale = "This content violates community guidelines."
embedding = embed_moderation_rationale(rationale)
print(embedding)

def local_request(text: str) -> dict:
    return {"text": text}


def local_response(response: dict) -> str:
    return response.get('safety_result', '')


def normalize_text(text: str) -> str:
    return text.strip().lower()

import boto3

def analyze_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    score = response['SentimentScore'][sentiment]
    return sentiment, score

def is_safe(text, threshold=0.5):
    sentiment, score = analyze_text(text)
    if sentiment == 'POSITIVE' and score > threshold:
        return True
    else:
        return False

import boto3

comprehend = boto3.client('comprehend')

def redact_unsafe(text):
    response = comprehend.detect_pii_entities(Text=text, LanguageCode='en')
    redacted_text = text
    for entity in response['Entities']:
        if entity['Type'] in ['BANK_ACCOUNT_NUMBER', 'CREDIT_DEBIT_NUMBER', 'PASSPORT_NUMBER']:
            redacted_text = redacted_text.replace(entity['Text'], '[REDACTED]')
    return redacted_text

import boto3

def moderate_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': text
            }
        ],
        LanguageCode='en'
    )
    return response

if __name__ == '__main__'):
    user_text = input('Enter text to moderate: ')
    result = moderate_text(user_text)
    print(result)
